INSERT INTO "quests" VALUES ('8001', 'main', '初入大陆', '拜访大陆传送官，了解这片大陆的现状。', '', 1, '0002', 'talk', '0002', 1, 500, 100, '[]', 0);
INSERT INTO "quests" VALUES ('8002', 'main', '除鸡令', '村外的赤焰斗鸡扰民已久，替传送官清理 5 只。', '8001', 1, '0002', 'kill', '1', 5, 800, 200, '[{"goodId":"material_hide","count":2}]', 0);
INSERT INTO "quests" VALUES ('8003', 'main', '皮料筹措', '传送官要修补货车，交付 3 张兽皮（material_hide）。', '8002', 1, '0002', 'collect', 'material_hide', 3, 1000, 300, '[{"goodId":"material_iron","count":1}]', 0);
INSERT INTO "quests" VALUES ('8004', 'main', '战魂之门', '带着铁料去见战魂使者，开启战魂之路。', '8003', 1, '9002', 'talk', '9002', 1, 1500, 500, '[]', 0);
INSERT INTO "quests" VALUES ('8101', 'daily', '日常巡猎', '每日例行：猎杀 10 只金斑雄鹿，维持村郊安宁。', '', 1, '0002', 'kill', '2', 10, 500, 150, '[]', 0);
INSERT INTO "ranks" VALUES (1, '新兵', '兵卒', '刚入伍的毛头小子，铁甲还带着新铁的凉气。', 30, 41, 0, 6, 8, 6, 8, 6, 8, 2, 2, 2, 2, 2, 2, 0);
INSERT INTO "ranks" VALUES (2, '列兵', '兵卒', '站得笔直的列兵，喊起号子来最有精神。', 120, 45, 0, 7, 9, 7, 9, 7, 9, 2, 3, 2, 3, 2, 3, 0);
INSERT INTO "ranks" VALUES (3, '上等兵', '兵卒', '操练最勤的上等兵，教头已经记住了他的名字。', 270, 49, 0, 7, 10, 7, 10, 7, 10, 2, 3, 2, 3, 2, 3, 0);
INSERT INTO "ranks" VALUES (4, '伍长', '兵卒', '带五个人的伍长，第一次有了要照看的兄弟。', 480, 52, 1, 8, 11, 8, 11, 8, 11, 2, 3, 2, 3, 2, 3, 0);
INSERT INTO "ranks" VALUES (5, '什长', '兵卒', '管十个兄弟的什长，夜里替人站过岗。', 750, 56, 1, 8, 12, 8, 12, 8, 12, 2, 3, 2, 3, 2, 3, 0);
INSERT INTO "ranks" VALUES (6, '队正', '兵卒', '领一队人的队正，号令一出队伍立即成列。', 1080, 60, 1, 9, 13, 9, 13, 9, 13, 2, 3, 2, 3, 2, 3, 0);
INSERT INTO "ranks" VALUES (7, '屯长', '兵卒', '屯田练兵的屯长，粮草与刀枪一起管。', 1470, 63, 1, 9, 13, 9, 13, 9, 13, 3, 4, 3, 4, 3, 4, 0);
INSERT INTO "ranks" VALUES (8, '曲长', '兵卒', '领一曲之兵的曲长，第一次独立列阵迎敌。', 1920, 67, 1, 10, 14, 10, 14, 10, 14, 3, 4, 3, 4, 3, 4, 0);
INSERT INTO "ranks" VALUES (9, '部曲督', '兵卒', '督领部曲的军官，营中大小事务都要过他手。', 2430, 71, 1, 11, 15, 11, 15, 11, 15, 3, 4, 3, 4, 3, 4, 0);
INSERT INTO "ranks" VALUES (10, '牙门将', '兵卒', '牙门之下执旗的将领，自此正式踏上仕途。', 3000, 75, 1, 11, 16, 11, 16, 11, 16, 3, 4, 3, 4, 3, 4, 0);
INSERT INTO "ranks" VALUES (11, '陪戎校尉', '校尉', '陪侍军旅的散号校尉，算是有了正经品级。', 3630, 82, 1, 12, 17, 12, 17, 12, 17, 3, 5, 3, 5, 3, 5, 0);
INSERT INTO "ranks" VALUES (12, '仁勇校尉', '校尉', '仁而能勇的校尉，士卒愿意跟着他冲锋。', 4320, 86, 1, 13, 18, 13, 18, 13, 18, 3, 5, 3, 5, 3, 5, 0);
INSERT INTO "ranks" VALUES (13, '致果校尉', '校尉', '果决敢断的校尉，箭雨之中也不退半步。', 5070, 90, 1, 13, 19, 13, 19, 13, 19, 4, 5, 4, 5, 4, 5, 0);
INSERT INTO "ranks" VALUES (14, '翊麾校尉', '校尉', '翊卫麾下的校尉，护着帅旗不离左右。', 5880, 94, 1, 14, 20, 14, 20, 14, 20, 4, 5, 4, 5, 4, 5, 0);
INSERT INTO "ranks" VALUES (15, '宣节校尉', '校尉', '掌宣威持节的校尉，出使诸营传令。', 6750, 101, 1, 15, 21, 15, 21, 15, 21, 4, 6, 4, 6, 4, 6, 0);
INSERT INTO "ranks" VALUES (16, '游骑校尉', '校尉', '率游骑巡哨的校尉，来去如风不留踪迹。', 7680, 116, 1, 15, 22, 15, 22, 15, 22, 5, 6, 5, 6, 5, 6, 0);
INSERT INTO "ranks" VALUES (17, '昭武校尉', '校尉', '昭显武德的校尉，演武场上连克三营。', 8670, 129, 1, 17, 24, 17, 24, 17, 24, 5, 7, 5, 7, 5, 7, 0);
INSERT INTO "ranks" VALUES (18, '振威校尉', '校尉', '振扬军威的校尉，一声怒喝能止住溃兵。', 9720, 142, 1, 19, 27, 19, 27, 19, 27, 5, 8, 5, 8, 5, 8, 0);
INSERT INTO "ranks" VALUES (19, '果毅校尉', '校尉', '果毅敢死的校尉，攻坚拔寨从不落于人后。', 10830, 155, 1, 20, 29, 20, 29, 20, 29, 6, 8, 6, 8, 6, 8, 0);
INSERT INTO "ranks" VALUES (20, '折冲校尉', '校尉', '折冲御侮的校尉，能挡下敌军第一波冲阵。', 12000, 167, 2, 22, 31, 22, 31, 22, 31, 6, 9, 6, 9, 6, 9, 0);
INSERT INTO "ranks" VALUES (21, '建节都尉', '都尉', '持节建威的都尉，可代主帅行令。', 13230, 189, 2, 25, 35, 25, 35, 25, 35, 7, 10, 7, 10, 7, 10, 0);
INSERT INTO "ranks" VALUES (22, '奉车都尉', '都尉', '掌车驾仪仗的都尉，出入军前最是显赫。', 14520, 202, 2, 27, 38, 27, 38, 27, 38, 8, 11, 8, 11, 8, 11, 0);
INSERT INTO "ranks" VALUES (23, '强弩都尉', '都尉', '统强弩营的都尉，箭阵所过寸草不生。', 15870, 215, 2, 28, 40, 28, 40, 28, 40, 8, 11, 8, 11, 8, 11, 0);
INSERT INTO "ranks" VALUES (24, '骑都尉', '都尉', '统骑军的都尉，马蹄声起便是敌营噩梦。', 17280, 229, 2, 30, 43, 30, 43, 30, 43, 8, 12, 8, 12, 8, 12, 0);
INSERT INTO "ranks" VALUES (25, '轻车都尉', '都尉', '领轻车的都尉，驰突如风不留痕迹。', 18750, 242, 2, 32, 45, 32, 45, 32, 45, 9, 13, 9, 13, 9, 13, 0);
INSERT INTO "ranks" VALUES (26, '奉国都尉', '都尉', '奉国讨逆的都尉，凡有战事必在其列。', 20280, 255, 3, 34, 48, 34, 48, 34, 48, 9, 13, 9, 13, 9, 13, 0);
INSERT INTO "ranks" VALUES (27, '护军都尉', '都尉', '掌护军的都尉，兼管诸营军法。', 21870, 269, 3, 35, 50, 35, 50, 35, 50, 10, 14, 10, 14, 10, 14, 0);
INSERT INTO "ranks" VALUES (28, '中垒都尉', '都尉', '领中垒营的都尉，是中军最硬的一面盾。', 23520, 282, 3, 37, 53, 37, 53, 37, 53, 10, 15, 10, 15, 10, 15, 0);
INSERT INTO "ranks" VALUES (29, '虎贲都尉', '都尉', '统虎贲锐士的都尉，专破敌之精锐。', 25230, 295, 3, 39, 55, 39, 55, 39, 55, 11, 15, 11, 15, 11, 15, 0);
INSERT INTO "ranks" VALUES (30, '羽林都尉', '都尉', '统羽林禁军的都尉，拱卫中军大帐。', 27000, 309, 3, 40, 58, 40, 58, 40, 58, 11, 16, 11, 16, 11, 16, 0);
INSERT INTO "ranks" VALUES (31, '五官中郎将', '中郎将', '五官中郎将，位列诸郎将之首。', 28830, 336, 3, 44, 63, 44, 63, 44, 63, 12, 18, 12, 18, 12, 18, 0);
INSERT INTO "ranks" VALUES (32, '左中郎将', '中郎将', '左中郎将，领左军宿卫。', 30720, 361, 4, 47, 66, 47, 66, 47, 66, 13, 19, 13, 19, 13, 19, 0);
